//! Compares formel's layout with what LuaTeX makes of the same formula.
//!
//! The cases are in `tex_oracle/cases.tsv` (LaTeX, the source of each case). For each there is
//!
//! - `tex_oracle/golden.tsv`: the width, height and depth LuaLaTeX gives it, with the same Latin
//!   Modern Math file as this test uses,
//! - `tex_oracle/mathml.tsv`: the MathML we take to be the same formula. It is written by hand,
//!   whatever it was first derived from; a new case needs its row there as well.
//!
//! `golden.tsv` is generated by `tex_oracle/generate.py`. Running this test needs no TeX: it lays
//! the MathML out and compares. Print the MathML of each case with `-- --nocapture`.
//!
//! Cases where formel and TeX are known to differ are listed in `KNOWN_DIFFERENCES`. They are
//! expected to keep differing, so one that starts to match fails the test and has to be removed
//! from the list.
#![cfg(feature = "mathml_parser")]

use std::collections::BTreeMap;

use formel::host::{Fragment, MathFont, MathStyle};
use formel::mathmlparser;
use formel::standalone::StyleOptions;

mod util;
use crate::util::TEST_FONT;

const CASES: &str = include_str!("tex_oracle/cases.tsv");
const MATHML: &str = include_str!("tex_oracle/mathml.tsv");
const GOLDEN: &str = include_str!("tex_oracle/golden.tsv");
const GLYPHS: &str = include_str!("tex_oracle/glyphs.tsv");

/// Allowed difference in font units (1000 per em). TeX rounds to 1/65536pt; this leaves room for
/// f32 arithmetic and for the half-unit rounding of glyph metrics.
const TOLERANCE: f32 = 3.0;

/// Cases where formel and TeX differ on purpose or for a reason not yet resolved, with why.
///
/// Each reason starts with how well it is established: `verified` (isolated or checked arithmetic),
/// `suspected` (fits the numbers and the MathML, not isolated) or `unexplained`.
const KNOWN_DIFFERENCES: &[(&str, &str)] = &[
    // TeX centres every large operator on the math axis, MathML Core only stretches (and so
    // centres) it in display style. The text size `\bigcup` reaches from -272 to 750, so its middle
    // is at 239: TeX moves it up 11 units to the axis at 250, here it stays.
    ("bigop-bigcup-ord-after", "verified: not centred on the axis in text style (11 units)"),
    // MathML Core keeps an operator's lspace/rspace at the edge of the formula, TeX drops it:
    // a lone `=` is 1334 wide here and 778 in TeX.
    ("overset", "verified: relation spacing kept at the edges of the formula, TeX drops it"),
    // The italic correction of a letter. TeX adds it before the next letter or sign, whatever that
    // is, except before explicit glue (`\,`). MathML Core adds it before the next child of a row
    // that is not slanted, that is, not a glyph with a correction of its own, and so also before
    // an explicit space. A letter followed by an upright `x` (which has a correction of 16) is
    // the first case: TeX adds the correction of the first letter (7 for `n`, 90 for `f`), Core not.
    ("italic-corr-upright-then-space", "verified: Core adds the italic correction of `n` (7) before the explicit space, TeX not"),
    ("italic-corr-upright-then-upright", "verified: TeX adds the italic correction of `n` (7) before an upright x, Core not"),
    ("italic-corr-italic-then-upright", "verified: TeX adds the italic correction of `f` (90) before an upright x, Core not"),
    ("lim-text", "unexplained: TeX is 5 units wider"),
    ("italic-corr-italic-then-space", "verified: MathML Core adds `f`'s italic correction (90) before the explicit space, TeX adds none"),
    // TeX sets the limit of \lim like that of a large operator (LowerLimitGapMin, 167). `lim` is an
    // `<mi>`, so MathML uses UnderbarVerticalGap (120): 167 - 120 = 47.
    ("lim-display", "verified: lower limit gap 120 (UnderbarVerticalGap) vs 167 (LowerLimitGapMin)"),
    // Delimiters. TeX takes the smallest variant of at least max(0.901 * 2D, 2D - 500) units, D
    // being the larger distance of the content from the axis (\delimiterfactor and
    // \delimitershortfall); MathML takes the smallest one that covers the content. For
    // \left(\frac{a}{b}\right), 1816 units tall, TeX's target is 1706 and it picks the 1793 unit
    // parenthesis, MathML picks the 2093 one: 150 more on each side. For the 2400 units of the
    // matrix below the targets are 2162 (the 2393 parenthesis) and 2400 (the 2991 one): 295 more
    // on each side.
    ("paren-fraction", "verified: TeX picks the 1793 parenthesis (target 1706), MathML the 2093 one (content 1816)"),
    ("paren-brace", "verified: TeX picks the 1801 brace, MathML the 2101 one (see paren-fraction)"),
    ("bar-evaluation", "verified: TeX picks the 1735 bar, MathML the 2085 one (see paren-fraction)"),
    ("fence-bar-tall", "verified: the variant choice of paren-fraction, for the bar"),
    ("fence-doublebar-tall", "verified: the variant choice of paren-fraction, for the double bar"),
    ("fence-floor-tall", "verified: the variant choice of paren-fraction, for the floor brackets"),
    ("fence-ceil-tall", "verified: the variant choice of paren-fraction, for the ceiling brackets"),
    ("fence-angle-tall", "verified: the variant choice of paren-fraction, for the angle brackets"),
    ("fence-bracket-tall", "verified: the variant choice of paren-fraction, for the square brackets"),
    // \binom: TeX uses the 2991 unit parenthesis in display style, MathML the 2093 one that covers
    // the content. Why TeX's is so large (a fixed size for the delimiters of a fraction, not one
    // taken from the content) was not checked.
    ("binom", "suspected: TeX's 2991 unit parentheses vs the 2093 ones that cover the content"),
    ("binom-text", "suspected: a fixed delimiter size in TeX vs delimiters that cover the content"),
    // The table of the matrix matches TeX (matrix-bare); its parentheses are the delimiter
    // choice above, 2393 for TeX and 2991 here, and wider for the larger one.
    ("matrix-2x2", "verified: the parentheses (2393 vs 2991 units), the table itself matches"),
    // Braces. TeX takes the largest brace variant not wider than the base (3503 units for a base
    // of 4000, reaching 845 above the baseline), MathML Core the smallest one at least as wide
    // (4007, reaching 854): 9 units. Labels: TeX sets them like the limits of a large operator
    // (UpperLimitGapMin 200 above; below the larger of LowerLimitGapMin 167 and LowerLimitBaselineDropMin
    // 600 minus the label's height, 291 for a script-size `n`), MathML like any other script over
    // an overbar or underbar (OverbarVerticalGap and UnderbarVerticalGap, 120 each).
    ("brace-over-bare", "verified: brace variant 4007 wide (top 854), TeX uses 3503 (top 845)"),
    ("brace-over-bare-text", "verified: brace variant 4007 wide (top 854), TeX uses 3503 (top 845)"),
    ("brace-under-bare", "verified: brace variant 4007 wide (bottom -423), TeX uses 3503 (-414)"),
    ("brace-under-bare-text", "verified: brace variant 4007 wide (bottom -423), TeX uses 3503 (-414)"),
    ("overbrace", "verified: label gap 120 vs 200 (-80), brace variant +9"),
    ("brace-over-label-text", "verified: label gap 120 vs 200 (-80), brace variant +9"),
    ("underbrace", "verified: label gap 120 vs 291 (-171), brace variant +9"),
    ("brace-under-label-text", "verified: label gap 120 vs 291 (-171), brace variant +9"),
    // TeX draws \overline and \underline as a rule 120 units from the base, 40 thick, with 40 more
    // above: the top of `x+y` (583) plus 200, 783 (and 205 + 200 = 405 below). Here the stretchy
    // accent glyph is placed like any accent: the top of the combining overline is at 670, raised
    // by the height of the base above the accent base height, 583 - 450 = 133, which is 803; the
    // combining low line reaches down to -143 below the 205 of the base, which is 348.
    ("overline", "verified: accent glyph top 803 vs TeX's rule at 783"),
    ("underline", "verified: accent glyph bottom 348 vs TeX's rule at 405"),
    // TeX adds no italic correction before a fraction; MathML Core does, as a fraction is not slanted.
    ("italic-corr-letter-fraction", "verified: `f`'s italic correction (90) added before a fraction, TeX adds none"),
    ("sqrt-index-tall", "unexplained: 4.5 units wider, root degree"),
];

/// The cases whose glyph positions are compared with TeX's: the accents, whose horizontal position
/// (the top accent attachment of the base against that of the accent) shows nowhere in the size of
/// the formula. The other cases are not compared glyph by glyph yet: they differ in places, for
/// example in how a fraction centres its numerator.
const GLYPH_CHECKED: &str = "accent-";

/// Cases among those that are not where TeX puts their glyphs (see `glyph_positions_match_tex`),
/// with why.
const KNOWN_GLYPH_DIFFERENCES: &[(&str, &str)] = &[
    // The combining circumflex has variants 365, 645, 769, 920, 1101, 1321, 1582 and 1897 wide.
    // TeX takes the largest that is not wider than the base, MathML Core the smallest that is at
    // least as wide. `abc` is 1405 wide: TeX takes 1321 (glyph 2315), here 1582 (glyph 2325); `ab`
    // is 958 wide: 920 (2295) against 1101 (2305). Where the base is wider than the largest
    // variant both take that one.
    ("accent-widehat", "verified: wide hat variant 1582 (covers the base) vs TeX's 1321 (fits in it)"),
    ("accent-widehat-two", "verified: wide hat variant 1101 (covers the base) vs TeX's 920 (fits in it)"),
];

#[derive(Debug, Clone, Copy)]
struct Boxed {
    width: f32,
    height: f32,
    depth: f32,
}

/// The tab separated rows of a data file, without comments.
fn rows(text: &str) -> impl Iterator<Item = Vec<&str>> {
    text.lines()
        .filter(|l| !l.trim().is_empty() && !l.starts_with('#'))
        .map(|l| l.split('\t').collect())
}

/// The size of the formula at one em per 1000 font units, inline unless the MathML says
/// `display="block"`.
fn layout_box(mathml: &str) -> Boxed {
    TEST_FONT.with(|font| {
        let doc = mathmlparser::parse(mathml.as_bytes()).expect("valid MathML");
        let options = StyleOptions {
            font_size: font.units_per_em() as f32,
            math_style: MathStyle::Compact,
        };
        let result = formel::layout(&doc, font, options);
        let layout = &result.layouts[&doc.root().unwrap()];
        Boxed {
            width: layout.size.width,
            height: layout.baseline,
            depth: layout.size.height - layout.baseline,
        }
    })
}

#[test]
fn layout_matches_tex() {
    let golden: BTreeMap<&str, Boxed> = rows(GOLDEN)
        .map(|r| {
            let n = |i: usize| r[i].parse::<f32>().unwrap();
            (r[0], Boxed { width: n(2), height: n(3), depth: n(4) })
        })
        .collect();
    let mathml: BTreeMap<&str, &str> = rows(MATHML).map(|r| (r[0], r[1])).collect();

    let mut unexpected = vec![];
    let mut table = String::new();
    for row in rows(CASES) {
        let (name, latex) = (row[0], row[2]);
        let tex = golden[name];
        let ours = layout_box(mathml[name]);
        let diff = [ours.width - tex.width, ours.height - tex.height, ours.depth - tex.depth];
        let matches = diff.iter().all(|d| d.abs() <= TOLERANCE);
        let known = KNOWN_DIFFERENCES.iter().find(|(n, _)| *n == name);
        table += &format!(
            "{:<24} {} {:>6.1} {:>6.1} {:>6.1}   {}\n    {latex}\n    {}\n",
            name,
            if matches { "ok  " } else { "DIFF" },
            diff[0], diff[1], diff[2],
            known.map_or("", |(_, why)| *why),
            mathml[name],
        );
        match (matches, known) {
            (false, None) => unexpected.push(format!(
                "{name}: formel minus TeX (width, height, depth) = {:+.1} {:+.1} {:+.1}\n    {latex}",
                diff[0], diff[1], diff[2]
            )),
            (true, Some(_)) => unexpected.push(format!(
                "{name} matches TeX now: remove it from KNOWN_DIFFERENCES"
            )),
            _ => {}
        }
    }
    println!("name  (formel - TeX: width height depth, font units)\n{table}");
    assert!(unexpected.is_empty(), "\n{}\n", unexpected.join("\n"));
}

/// A glyph of a formula: its glyph index in the font, x from the left edge of the formula and y
/// up from its baseline, in font units.
type Glyph = (u32, f32, f32);

/// Every glyph that the layout of `mathml` draws, with its position.
fn layout_glyphs(mathml: &str) -> Vec<Glyph> {
    TEST_FONT.with(|font| {
        let doc = mathmlparser::parse(mathml.as_bytes()).expect("valid MathML");
        let options = StyleOptions {
            font_size: font.units_per_em() as f32,
            math_style: MathStyle::Compact,
        };
        let result = formel::layout(&doc, font, options);
        let root = doc.root().unwrap();
        let baseline = result.layouts[&root].baseline;
        let mut glyphs = vec![];
        // locations are relative to the parent, y points down
        let mut stack = vec![(root, 0.0, 0.0)];
        while let Some((node, parent_x, parent_y)) = stack.pop() {
            let Some(layout) = result.layouts.get(&node) else { continue };
            let (x, y) = (parent_x + layout.location.x, parent_y + layout.location.y);
            for fragment in &layout.fragments {
                if let Fragment::Glyphs { origin, glyphs: run, .. } = fragment {
                    for g in run {
                        glyphs.push((
                            g.glyph as u32,
                            x + origin.x + g.offset.x,
                            baseline - (y + origin.y + g.offset.y),
                        ));
                    }
                }
            }
            stack.extend(doc.node(node).children.iter().map(|&child| (child, x, y)));
        }
        glyphs
    })
}

/// How the glyphs of the layout differ from TeX's, if they do: other glyphs, or one that is
/// more than TOLERANCE away from where TeX has it. The glyphs are paired by glyph index, in
/// order from left to right.
fn glyph_difference(tex: &[Glyph], ours: &[Glyph]) -> Option<String> {
    let by_index = |glyphs: &[Glyph]| {
        let mut map: BTreeMap<u32, Vec<(f32, f32)>> = BTreeMap::new();
        for &(index, x, y) in glyphs {
            map.entry(index).or_default().push((x, y));
        }
        for positions in map.values_mut() {
            positions.sort_by(|a, b| a.partial_cmp(b).unwrap());
        }
        map
    };
    let (tex, ours) = (by_index(tex), by_index(ours));
    let indices = |m: &BTreeMap<u32, Vec<(f32, f32)>>| {
        m.iter().flat_map(|(i, p)| std::iter::repeat_n(*i, p.len())).collect::<Vec<_>>()
    };
    if indices(&tex) != indices(&ours) {
        return Some(format!("other glyphs: TeX {:?}, formel {:?}", indices(&tex), indices(&ours)));
    }
    let mut worst: Option<(f32, String)> = None;
    for (index, positions) in &tex {
        for (t, o) in positions.iter().zip(&ours[index]) {
            let off = (o.0 - t.0).abs().max((o.1 - t.1).abs());
            if off > TOLERANCE && worst.as_ref().is_none_or(|(w, _)| off > *w) {
                worst = Some((
                    off,
                    format!("glyph {index}: TeX at ({:.1}, {:.1}), formel at ({:.1}, {:.1})", t.0, t.1, o.0, o.1),
                ));
            }
        }
    }
    worst.map(|(_, message)| message)
}

#[test]
fn glyph_positions_match_tex() {
    let mut tex: BTreeMap<&str, Vec<Glyph>> = BTreeMap::new();
    for row in rows(GLYPHS) {
        let n = |i: usize| row[i].parse::<f32>().unwrap();
        tex.entry(row[0]).or_default().push((row[1].parse().unwrap(), n(2), n(3)));
    }
    let mathml: BTreeMap<&str, &str> = rows(MATHML).map(|r| (r[0], r[1])).collect();

    let mut unexpected = vec![];
    for row in rows(CASES).filter(|r| r[0].starts_with(GLYPH_CHECKED)) {
        let name = row[0];
        let ours = layout_glyphs(mathml[name]);
        let difference = glyph_difference(tex.get(name).map_or(&[], |g| g), &ours);
        let known = KNOWN_GLYPH_DIFFERENCES.iter().find(|(n, _)| *n == name);
        match (difference, known) {
            (Some(message), None) => unexpected.push(format!("{name}: {message}")),
            (None, Some(_)) => unexpected.push(format!(
                "{name}: the glyphs match TeX now, remove it from KNOWN_GLYPH_DIFFERENCES"
            )),
            _ => {}
        }
    }
    assert!(unexpected.is_empty(), "\n{}\n", unexpected.join("\n"));
}

#[test]
fn every_case_has_a_measurement_and_mathml() {
    let names = |text| rows(text).map(|r| r[0]).collect::<Vec<_>>();
    let cases = names(CASES);
    assert_eq!(names(GOLDEN), cases, "golden.tsv is stale: run tex_oracle/generate.py");
    assert_eq!(names(MATHML), cases, "mathml.tsv has to have a row for every case of cases.tsv, in the same order");
    for (name, _) in KNOWN_DIFFERENCES {
        assert!(cases.contains(name), "KNOWN_DIFFERENCES has {name}, which is not a case");
    }
}
